1: /**
2:  * Church Application Backend & Bible API Server
3:  * Built with native Node.js HTTP module (zero external dependencies).
4:  * Serves church website assets and provides Bible API endpoints.
5:  */
6: 
7: const http = require('http');
8: const fs = require('fs');
9: const path = require('path');
10: const url = require('url');
11: 
12: const PORT = process.env.PORT || 3000;
13: const PUBLIC_DIR = __dirname;
14: const BIBLE_DATA_DIR = path.join(__dirname, 'bible-data');
15: 
16: // Load books metadata into memory
17: let booksMeta = [];
18: let booksBySlug = new Map();
19: let booksByName = new Map();
20: let booksById = new Map();
21: 
22: function loadMetadata() {
23:   const booksPath = path.join(BIBLE_DATA_DIR, 'books.json');
24:   if (fs.existsSync(booksPath)) {
25:     booksMeta = JSON.parse(fs.readFileSync(booksPath, 'utf8'));
26:     booksBySlug.clear();
27:     booksByName.clear();
28:     booksById.clear();
29:     for (const b of booksMeta) {
30:       booksBySlug.set(b.slug.toLowerCase(), b);
31:       booksByName.set(b.name.toLowerCase(), b);
32:       booksByName.set(b.teluguName.toLowerCase(), b);
33:       booksById.set(b.id, b);
34:     }
35:   }
36: }
37: 
38: loadMetadata();
39: 
40: // Load daily verses
41: let dailyVerses = [];
42: const dailyVersesPath = path.join(BIBLE_DATA_DIR, 'daily-verses.json');
43: if (fs.existsSync(dailyVersesPath)) {
44:   dailyVerses = JSON.parse(fs.readFileSync(dailyVersesPath, 'utf8'));
45: }
46: 
47: // In-memory cache for book JSON contents
48: const bookCache = new Map();
49: 
50: function getBookData(translation, bookMeta) {
51:   const cacheKey = `${translation}:${bookMeta.slug}`;
52:   if (bookCache.has(cacheKey)) {
53:     return bookCache.get(cacheKey);
54:   }
55:   const fileName = translation === 'telugu' ? bookMeta.teluguFile : bookMeta.kjvFile;
56:   const folder = translation === 'telugu' ? 'telugu' : 'kjv';
57:   const fullPath = path.join(BIBLE_DATA_DIR, folder, fileName);
58: 
59:   if (!fs.existsSync(fullPath)) {
60:     return null;
61:   }
62: 
63:   const content = JSON.parse(fs.readFileSync(fullPath, 'utf8'));
64:   bookCache.set(cacheKey, content);
65:   return content;
66: }
67: 
68: // Fast verse search engine
69: function searchVerses({ query, translation = 'kjv', testament = 'all', bookSlug = null, limit = 50 }) {
70:   const cleanQ = (query || '').trim().toLowerCase();
71:   if (!cleanQ) {
72:     return { query, total: 0, results: [] };
73:   }
74: 
75:   // Pre-load all books if searching full Bible
76:   const results = [];
77:   const targetBooks = booksMeta.filter(b => {
78:     if (testament !== 'all' && b.testament.toLowerCase() !== testament.toLowerCase()) {
79:       return false;
80:     }
81:     if (bookSlug && b.slug !== bookSlug && b.name.toLowerCase() !== bookSlug.toLowerCase()) {
82:       return false;
83:     }
84:     return true;
85:   });
86: 
87:   for (const b of targetBooks) {
88:     const data = getBookData(translation, b);
89:     if (!data || !data.chapters) continue;
90: 
91:     for (const ch of data.chapters) {
92:       const chNum = ch.chapter;
93:       for (const v of ch.verses) {
94:         const text = v.text || '';
95:         const matchIndex = text.toLowerCase().indexOf(cleanQ);
96:         if (matchIndex !== -1) {
97:           results.push({
98:             bookId: b.id,
99:             bookSlug: b.slug,
100:             bookName: b.name,
101:             teluguBookName: b.teluguName,
102:             chapter: parseInt(chNum, 10),
103:             verse: parseInt(v.verse, 10),
104:             referenceEn: `${b.name} ${chNum}:${v.verse}`,
105:             referenceTe: `${b.teluguName} ${chNum}:${v.verse}`,
106:             text: text,
107:             matchIndex: matchIndex,
108:             translation: translation
109:           });
110: 
111:           if (results.length >= limit) {
112:             return {
113:               query,
114:               translation,
115:               testament,
116:               total: results.length,
117:               hasMore: true,
118:               results
119:             };
120:           }
121:         }
122:       }
123:     }
124:   }
125: 
126:   return {
127:     query,
128:     translation,
129:     testament,
130:     total: results.length,
131:     hasMore: false,
132:     results
133:   };
134: }
