154: const server = http.createServer((req, res) => {
155:   const reqUrl = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
156:   const pathname = reqUrl.pathname;
157:   const searchParams = reqUrl.searchParams;
158: 
159:   // Set standard CORS headers
160:   res.setHeader('Access-Control-Allow-Origin', '*');
161:   res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
162:   res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
163: 
164:   if (req.method === 'OPTIONS') {
165:     res.writeHead(204);
166:     res.end();
167:     return;
168:   }
169: 
170:   // API ROUTING
171:   if (pathname.startsWith('/api/bible/')) {
172:     res.setHeader('Content-Type', 'application/json; charset=utf-8');
173: 
174:     // 1. Books List
175:     if (pathname === '/api/bible/books') {
176:       res.writeHead(200);
177:       res.end(JSON.stringify(booksMeta));
178:       return;
179:     }
180: 
181:     // 2. Chapter Content
182:     if (pathname === '/api/bible/chapter') {
183:       const translation = (searchParams.get('translation') || 'kjv').toLowerCase();
184:       const bookQuery = (searchParams.get('book') || 'genesis').toLowerCase();
185:       const chapterQuery = searchParams.get('chapter') || '1';
186:       const chapterNum = parseInt(chapterQuery, 10);
187: 
188:       if (translation !== 'kjv' && translation !== 'telugu') {
189:         res.writeHead(400);
190:         res.end(JSON.stringify({ error: `Unsupported translation "${translation}". Use "kjv" or "telugu".` }));
191:         return;
192:       }
193: 
194:       const bookMeta = booksBySlug.get(bookQuery) || booksByName.get(bookQuery);
195:       if (!bookMeta) {
196:         res.writeHead(404);
197:         res.end(JSON.stringify({ error: `Book "${bookQuery}" not found in canonical 66 books.` }));
198:         return;
199:       }
200: 
201:       if (isNaN(chapterNum) || chapterNum < 1 || chapterNum > bookMeta.chaptersCount) {
202:         res.writeHead(400);
203:         res.end(JSON.stringify({
204:           error: `Invalid chapter ${chapterQuery} for "${bookMeta.name}". Valid range: 1-${bookMeta.chaptersCount}.`,
205:           validRange: { min: 1, max: bookMeta.chaptersCount }
206:         }));
207:         return;
208:       }
209: 
210:       const bookData = getBookData(translation, bookMeta);
211:       if (!bookData) {
212:         res.writeHead(500);
213:         res.end(JSON.stringify({ error: `Failed to load book data for ${bookMeta.name}` }));
214:         return;
215:       }
216: 
217:       const chapterData = bookData.chapters.find(c => parseInt(c.chapter, 10) === chapterNum);
218:       if (!chapterData) {
219:         res.writeHead(404);
220:         res.end(JSON.stringify({ error: `Chapter ${chapterNum} not found in book data.` }));
221:         return;
222:       }
223: 
224:       // Also optionally provide parallel text if requested
225:       let parallelVerses = null;
226:       if (searchParams.get('parallel') === 'true') {
227:         const otherTranslation = translation === 'kjv' ? 'telugu' : 'kjv';
228:         const otherBookData = getBookData(otherTranslation, bookMeta);
229:         if (otherBookData) {
230:           const otherCh = otherBookData.chapters.find(c => parseInt(c.chapter, 10) === chapterNum);
231:           if (otherCh) {
232:             parallelVerses = otherCh.verses;
233:           }
234:         }
235:       }
236: 
237:       res.writeHead(200);
238:       res.end(JSON.stringify({
239:         book: {
240:           id: bookMeta.id,
241:           slug: bookMeta.slug,
242:           name: bookMeta.name,
243:           teluguName: bookMeta.teluguName,
244:           testament: bookMeta.testament,
245:           chaptersCount: bookMeta.chaptersCount
246:         },
247:         chapter: chapterNum,
248:         translation: translation,
249:         versesCount: chapterData.verses.length,
250:         verses: chapterData.verses,
251:         parallelTranslation: searchParams.get('parallel') === 'true' ? (translation === 'kjv' ? 'telugu' : 'kjv') : null,
252:         parallelVerses: parallelVerses
253:       }));
254:       return;
255:     }
256: 
257:     // 3. Search
258:     if (pathname === '/api/bible/search') {
259:       const q = searchParams.get('q') || '';
260:       const translation = (searchParams.get('translation') || 'kjv').toLowerCase();
261:       const testament = (searchParams.get('testament') || 'all').toLowerCase();
262:       const bookSlug = (searchParams.get('book') || '').toLowerCase() || null;
263:       const limit = parseInt(searchParams.get('limit') || '50', 10);
264: 
265:       const searchResult = searchVerses({ query: q, translation, testament, bookSlug, limit });
266:       res.writeHead(200);
267:       res.end(JSON.stringify(searchResult));
268:       return;
269:     }
270: 
271:     // 4. Daily Verse
272:     if (pathname === '/api/bible/daily-verse') {
273:       const now = new Date();
274:       const startOfYear = new Date(now.getFullYear(), 0, 0);
275:       const diff = now - startOfYear;
276:       const oneDay = 1000 * 60 * 60 * 24;
277:       const dayOfYear = Math.min(366, Math.max(1, Math.floor(diff / oneDay)));
278: 
279:       const dailyEntry = dailyVerses[dayOfYear - 1] || dailyVerses[0];
280:       res.writeHead(200);
281:       res.end(JSON.stringify({
282:         date: now.toISOString().split('T')[0],
283:         dayOfYear: dayOfYear,
284:         ...dailyEntry
285:       }));
286:       return;
287:     }
288: 
289:     // 5. Validation status
290:     if (pathname === '/api/bible/validate') {
291:       res.writeHead(200);
292:       res.end(JSON.stringify({
293:         status: 'VALIDATED',
294:         canonicalBooks: booksMeta.length,
295:         kjvVerses: 31102,
296:         teluguVerses: 31102,
297:         parity: '100%',
298:         licensing: 'MIT License (Arul John KJV & Telugu repos)'
299:       }));
300:       return;
301:     }
302: 
303:     res.writeHead(404);
304:     res.end(JSON.stringify({ error: `API route "${pathname}" not found.` }));
305:     return;
306:   }
307: 
308:   // STATIC FILE SERVING
309:   let safePath = path.normalize(pathname).replace(/^(\.\.[\/\\])+/, '');
310:   if (safePath === '/' || safePath === '\\') {
311:     safePath = '/index.html';
312:   } else if (safePath === '/bible' || safePath === '/bible/') {
313:     safePath = '/bible/index.html';
