326:     return;
327:   }
328: 
329:   const ext = path.extname(filePath).toLowerCase();
330:   const contentType = MIME_TYPES[ext] || 'application/octet-stream';
331: 
332:   // Cache policy
333:   if (ext === '.json' && filePath.includes('bible-data')) {
334:     res.setHeader('Cache-Control', 'public, max-age=86400, stale-while-revalidate=604800');
335:   }
336: 
337:   res.writeHead(200, { 'Content-Type': contentType });
338:   const stream = fs.createReadStream(filePath);
339:   stream.pipe(res);
