import {
  BookMeta,
  ChapterData,
  DailyVerse,
  SearchResponse,
  ChurchEvent,
  Sermon,
  Announcement,
  PrayerRequest,
  Bookmark,
  HealthStatus
} from '../types';

const API_BASE = '/api';

export const BibleAPI = {
  async getBooks(): Promise<BookMeta[]> {
    const res = await fetch(`${API_BASE}/bible/books`);
    if (!res.ok) throw new Error('Failed to load books metadata');
    return res.json();
  },

  async getChapter(
    book: string,
    chapter: number,
    translation: string = 'kjv',
    parallel: boolean = false
  ): Promise<ChapterData> {
    const url = `${API_BASE}/bible/chapter?book=${encodeURIComponent(book)}&chapter=${chapter}&translation=${translation}&parallel=${parallel}`;
    const res = await fetch(url);
    if (!res.ok) {
      const err = await res.json().catch(() => ({ detail: 'Failed to fetch chapter' }));
      throw new Error(err.detail || 'Failed to fetch chapter');
    }
    return res.json();
  },

  async searchScripture(
    q: string,
    translation: string = 'kjv',
    testament: string = 'all',
    book?: string,
    limit: number = 50
  ): Promise<SearchResponse> {
    let url = `${API_BASE}/bible/search?q=${encodeURIComponent(q)}&translation=${translation}&testament=${testament}&limit=${limit}`;
    if (book) {
      url += `&book=${encodeURIComponent(book)}`;
    }
    const res = await fetch(url);
    if (!res.ok) throw new Error('Search failed');
    return res.json();
  },

  async getDailyVerse(): Promise<DailyVerse> {
    const res = await fetch(`${API_BASE}/bible/daily-verse`);
    if (!res.ok) throw new Error('Failed to fetch daily verse');
    return res.json();
  },

  async getHealth(): Promise<HealthStatus> {
    const res = await fetch(`${API_BASE}/health`);
    if (!res.ok) throw new Error('Failed to fetch health status');
    return res.json();
  }
};

export const ChurchAPI = {
  async getEvents(): Promise<ChurchEvent[]> {
    const res = await fetch(`${API_BASE}/church/events`);
    if (!res.ok) throw new Error('Failed to fetch events');
    return res.json();
  },

  async getSermons(): Promise<Sermon[]> {
    const res = await fetch(`${API_BASE}/church/sermons`);
    if (!res.ok) throw new Error('Failed to fetch sermons');
    return res.json();
  },

  async getAnnouncements(): Promise<Announcement[]> {
    const res = await fetch(`${API_BASE}/church/announcements`);
    if (!res.ok) throw new Error('Failed to fetch announcements');
    return res.json();
  },

  async getPrayerRequests(): Promise<PrayerRequest[]> {
    const res = await fetch(`${API_BASE}/church/prayer-requests`);
    if (!res.ok) throw new Error('Failed to fetch prayer requests');
    return res.json();
  },

  async submitPrayerRequest(data: { name?: string; email?: string; request_text: string; is_anonymous: boolean }): Promise<PrayerRequest> {
    const res = await fetch(`${API_BASE}/church/prayer-requests`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    if (!res.ok) throw new Error('Failed to submit prayer request');
    return res.json();
  },

  async sendContact(data: { name: string; email: string; phone?: string; message: string }): Promise<any> {
    const res = await fetch(`${API_BASE}/church/contact`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    if (!res.ok) throw new Error('Failed to send contact message');
    return res.json();
  },

  async getBookmarks(userId: string = 'guest'): Promise<Bookmark[]> {
    const res = await fetch(`${API_BASE}/church/bookmarks?user_id=${userId}`);
    if (!res.ok) throw new Error('Failed to fetch bookmarks');
    return res.json();
  },

  async saveBookmark(bm: Bookmark): Promise<Bookmark> {
    const res = await fetch(`${API_BASE}/church/bookmarks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bm)
    });
    if (!res.ok) throw new Error('Failed to save bookmark');
    return res.json();
  },

  async deleteBookmark(id: number): Promise<void> {
    const res = await fetch(`${API_BASE}/church/bookmarks/${id}`, {
      method: 'DELETE'
    });
    if (!res.ok) throw new Error('Failed to delete bookmark');
  }
};

