import React, { useState, useEffect } from 'react';
import { BookMeta, ChapterData, Bookmark, SearchResultItem } from '../types';
import { BibleAPI, ChurchAPI } from '../services/api';

interface BibleReaderViewProps {
  books: BookMeta[];
  initialBookSlug?: string;
  initialChapter?: number;
}

export const BibleReaderView: React.FC<BibleReaderViewProps> = ({
  books,
  initialBookSlug = 'genesis',
  initialChapter = 1
}) => {
  // Navigation State
  const [selectedBookSlug, setSelectedBookSlug] = useState<string>(initialBookSlug);
  const [selectedChapter, setSelectedChapter] = useState<number>(initialChapter);
  const [translation, setTranslation] = useState<string>('kjv');
  const [parallel, setParallel] = useState<boolean>(false);
  const [fontSize, setFontSize] = useState<'sm' | 'md' | 'lg' | 'xl'>('md');

  // Sub-tab
  const [activeSubTab, setActiveSubTab] = useState<'reader' | 'search' | 'bookmarks'>('reader');

  // Chapter Content
  const [chapterData, setChapterData] = useState<ChapterData | null>(null);
  const [loadingChapter, setLoadingChapter] = useState<boolean>(false);
  const [chapterError, setChapterError] = useState<string | null>(null);

  // Search State
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [searchTranslation, setSearchTranslation] = useState<string>('kjv');
  const [searchTestament, setSearchTestament] = useState<string>('all');
  const [searchResults, setSearchResults] = useState<SearchResultItem[]>([]);
  const [searching, setSearching] = useState<boolean>(false);

  // Bookmarks State
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [noteInput, setNoteInput] = useState<{ [key: string]: string }>({});
  const [activeNoteVerse, setActiveNoteVerse] = useState<number | null>(null);
  const [toastMsg, setToastMsg] = useState<string | null>(null);

  // Book selector modal/dialog state
  const [showBookPicker, setShowBookPicker] = useState<boolean>(false);
  const [bookFilter, setBookFilter] = useState<string>('');

  const currentBook = books.find((b) => b.slug === selectedBookSlug) || books[0];

  const showToast = (msg: string) => {
    setToastMsg(msg);
    setTimeout(() => setToastMsg(null), 2500);
  };

  // Load Chapter Data
  useEffect(() => {
    if (!selectedBookSlug) return;
    loadChapter(selectedBookSlug, selectedChapter, translation, parallel);
  }, [selectedBookSlug, selectedChapter, translation, parallel]);

  // Load Bookmarks
  useEffect(() => {
    ChurchAPI.getBookmarks('guest')
      .then((data) => setBookmarks(data))
      .catch((err) => console.warn('Could not fetch bookmarks:', err));
  }, []);

  const loadChapter = async (
    bSlug: string,
    ch: number,
    trans: string,
    isParallel: boolean
  ) => {
    setLoadingChapter(true);
    setChapterError(null);
    try {
      const data = await BibleAPI.getChapter(bSlug, ch, trans, isParallel);
      setChapterData(data);
    } catch (err: any) {
      setChapterError(err.message || 'Error loading chapter verses.');
    } finally {
      setLoadingChapter(false);
    }
  };

  const handlePrevChapter = () => {
    if (selectedChapter > 1) {
      setSelectedChapter(selectedChapter - 1);
    } else {
      // Go to previous book if available
      const idx = books.findIndex((b) => b.slug === selectedBookSlug);
      if (idx > 0) {
        const prevB = books[idx - 1];
        setSelectedBookSlug(prevB.slug);
        setSelectedChapter(prevB.chaptersCount);
      }
    }
  };

  const handleNextChapter = () => {
    if (currentBook && selectedChapter < currentBook.chaptersCount) {
      setSelectedChapter(selectedChapter + 1);
    } else {
      // Go to next book if available
      const idx = books.findIndex((b) => b.slug === selectedBookSlug);
      if (idx !== -1 && idx < books.length - 1) {
        const nextB = books[idx + 1];
        setSelectedBookSlug(nextB.slug);
        setSelectedChapter(1);
      }
    }
  };

  // Search handler
  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!searchQuery.trim()) return;
    setSearching(true);
    try {
      const res = await BibleAPI.searchScripture(
        searchQuery,
        searchTranslation,
        searchTestament
      );
      setSearchResults(res.results || []);
    } catch (err) {
      showToast('Search encountered an issue');
    } finally {
      setSearching(false);
    }
  };

  // Copy verse
  const copyVerse = (vNum: number | string, text: string) => {
    const ref = `${currentBook?.name} ${selectedChapter}:${vNum}`;
    navigator.clipboard.writeText(`"${text}" - ${ref}`);
    showToast(`Copied ${ref}`);
  };

  // Save Bookmark
  const toggleBookmark = async (vNum: number, text: string) => {
    if (!currentBook) return;
    const existing = bookmarks.find(
      (b) =>
        b.book_slug === currentBook.slug &&
        b.chapter === selectedChapter &&
        b.verse === vNum
    );

    if (existing && existing.id) {
      try {
        await ChurchAPI.deleteBookmark(existing.id);
        setBookmarks(bookmarks.filter((b) => b.id !== existing.id));
        showToast(`Removed bookmark for verse ${vNum}`);
      } catch (err) {
        showToast('Failed to remove bookmark');
      }
    } else {
      const newBm: Bookmark = {
        user_id: 'guest',
        book_slug: currentBook.slug,
        book_name: currentBook.name,
        chapter: selectedChapter,
        verse: vNum,
        translation: translation,
        verse_text: text,
        note: noteInput[`${selectedChapter}:${vNum}`] || ''
      };
      try {
        const saved = await ChurchAPI.saveBookmark(newBm);
        setBookmarks([saved, ...bookmarks]);
        showToast(`Bookmarked ${currentBook.name} ${selectedChapter}:${vNum}`);
      } catch (err) {
        showToast('Failed to save bookmark');
      }
    }
  };

  // Voice speech synthesis read-aloud
  const speakVerse = (text: string, lang: string) => {
    if (!('speechSynthesis' in window)) {
      showToast('Speech synthesis not supported in this browser');
      return;
    }
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = lang === 'telugu' ? 'te-IN' : 'en-US';
    utterance.rate = 0.95;
    window.speechSynthesis.speak(utterance);
    showToast('Reading verse aloud 🔊');
  };

  // Jump from search result to reader
  const handleJumpToPassage = (bSlug: string, ch: number) => {
    setSelectedBookSlug(bSlug);
    setSelectedChapter(ch);
    setActiveSubTab('reader');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const otBooks = books.filter(
    (b) =>
      b.testament === 'OT' &&
      (b.name.toLowerCase().includes(bookFilter.toLowerCase()) ||
        b.teluguName.toLowerCase().includes(bookFilter.toLowerCase()))
  );
  const ntBooks = books.filter(
    (b) =>
      b.testament === 'NT' &&
      (b.name.toLowerCase().includes(bookFilter.toLowerCase()) ||
        b.teluguName.toLowerCase().includes(bookFilter.toLowerCase()))
  );

  return (
    <div className="bible-reader-view animate-fade-in">
      {/* Toast popup */}
      {toastMsg && <div className="toast-float">{toastMsg}</div>}

      {/* Top Bible Sub-Navigation Bar */}
      <div className="bible-nav-bar">
        <div className="bnb-left">
          <div className="sub-tab-group">
            <button
              className={`sub-tab-btn ${activeSubTab === 'reader' ? 'active' : ''}`}
              onClick={() => setActiveSubTab('reader')}
            >
              📖 Scripture Reader
            </button>
            <button
              className={`sub-tab-btn ${activeSubTab === 'search' ? 'active' : ''}`}
              onClick={() => setActiveSubTab('search')}
            >
              🔍 Search Bible
            </button>
            <button
              className={`sub-tab-btn ${activeSubTab === 'bookmarks' ? 'active' : ''}`}
              onClick={() => setActiveSubTab('bookmarks')}
            >
              🔖 Bookmarks &amp; Notes ({bookmarks.length})
            </button>
          </div>
        </div>

        <div className="bnb-right">
          {/* Translation selector */}
          <div className="translation-switch-group">
            <button
