                <div className="bpm-column">
                  <h4>Old Testament (పాత నిబంధన - 39 Books)</h4>
                  <div className="books-grid">
                    {otBooks.map((b) => (
                      <button
                        key={b.slug}
                        className={`book-item ${selectedBookSlug === b.slug ? 'selected' : ''}`}
                        onClick={() => {
                          setSelectedBookSlug(b.slug);
                          setSelectedChapter(1);
                          setShowBookPicker(false);
