                        b.book_slug === currentBook?.slug &&
                        b.chapter === selectedChapter &&
                        b.verse === vNum
                    );

                    return (
                      <div
                        key={vNum}
                        id={`verse-${vNum}`}
                        className={`verse-row ${isBookmarked ? 'bookmarked-row' : ''}`}
                      >
                        {/* Primary Verse */}
                        <div className="verse-primary-cell">
                          <span className="verse-number">{vNum}</span>
                          <span
                            className={`verse-text ${translation === 'telugu' ? 'telugu-text' : ''}`}
