                          </span>
                        </div>

                        {/* Parallel Verse (if enabled) */}
                        {parallel && parallelV && (
                          <div className="verse-parallel-cell">
                            <span className="verse-number parallel-num">{vNum}</span>
                            <span
                              className={`verse-text ${translation === 'kjv' ? 'telugu-text' : ''}`}
