                            className="va-btn"
                            onClick={() =>
                              setActiveNoteVerse(activeNoteVerse === vNum ? null : vNum)
                            }
                            title="Add study note"
                          >
                            📝
                          </button>
                        </div>

                        {/* Note Input Box if toggled */}
                        {activeNoteVerse === vNum && (
                          <div className="verse-note-box">
                            <textarea
                              placeholder={`Add your study reflection for verse ${vNum}...`}
                              value={noteInput[`${selectedChapter}:${vNum}`] || ''}
