                                setNoteInput({
                                  ...noteInput,
                                  [`${selectedChapter}:${vNum}`]: e.target.value
                                })
                              }
                              rows={2}
                            />
                            <div className="vnb-actions">
                              <button
                                className="btn-gold-sm"
                                onClick={() => {
                                  toggleBookmark(vNum, v.text);
                                  setActiveNoteVerse(null);
                                }}
