                  <button
                    className="btn-ch-nav"
                    onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                  >
                    ⬆ Top of Chapter
                  </button>
                  <button className="btn-ch-nav" onClick={handleNextChapter}>
                    Next Chapter ▶
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Sub-Tab: Search */}
      {activeSubTab === 'search' && (
        <div className="search-container animate-fade-in">
          <div className="search-header-card">
            <h2>Keyword Search in Holy Bible</h2>
            <p>Search across all 31,102 verses in English KJV or Telugu Bible</p>

            <form className="search-form" onSubmit={handleSearch}>
              <div className="search-input-wrap">
                <input
                  type="text"
                  placeholder="Enter keyword (e.g. grace, love, light, శాంతి, కృప, పరిశుద్ధ)..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="search-input"
                  autoFocus
                />
                <button type="submit" className="btn-primary" disabled={searching}>
                  {searching ? 'Searching...' : '🔍 Search'}
                </button>
              </div>

              <div className="search-filters-row">
                <label>
                  Translation:
                  <select
                    value={searchTranslation}
                    onChange={(e) => setSearchTranslation(e.target.value)}
                  >
                    <option value="kjv">English KJV</option>
                    <option value="telugu">తెలుగు (Telugu Bible)</option>
                  </select>
                </label>

                <label>
                  Testament:
                  <select
                    value={searchTestament}
                    onChange={(e) => setSearchTestament(e.target.value)}
                  >
                    <option value="all">Entire Bible (Old &amp; New)</option>
                    <option value="ot">Old Testament Only</option>
                    <option value="nt">New Testament Only</option>
                  </select>
                </label>
              </div>
            </form>
          </div>

          {/* Search Results */}
          <div className="search-results-list">
            {searching && (
              <div className="search-loading">
                <div className="spinner"></div>
                <p>Searching canonical Scripture...</p>
              </div>
            )}

            {!searching && searchResults.length > 0 && (
              <div className="results-wrapper">
                <div className="results-count">
                  Found <strong>{searchResults.length}</strong> matching verses for "{searchQuery}":
                </div>
                {searchResults.map((r, idx) => (
                  <div
                    key={idx}
                    className="search-result-card"
                    onClick={() => handleJumpToPassage(r.bookSlug, r.chapter)}
                  >
                    <div className="sr-header">
                      <span className="sr-ref">{r.referenceEn}</span>
                      <span className="sr-ref-te telugu-text">{r.referenceTe}</span>
                      <span className="sr-jump">Read in context ➔</span>
                    </div>
                    <p className={`sr-text ${r.translation === 'telugu' ? 'telugu-text' : ''}`}>
                      "{r.text}"
                    </p>
                  </div>
                ))}
              </div>
            )}

            {!searching && searchQuery && searchResults.length === 0 && (
              <div className="no-results">
                <p>No matching verses found for "{searchQuery}". Try a different word or translation.</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Sub-Tab: Bookmarks & Notes */}
      {activeSubTab === 'bookmarks' && (
        <div className="bookmarks-container animate-fade-in">
          <div className="bm-header-card">
            <h2>Saved Bookmarks &amp; Study Notes</h2>
            <p>Stored safely in your PostgreSQL / local church database</p>
          </div>

          {bookmarks.length === 0 ? (
            <div className="no-bookmarks">
              <span className="nb-icon">🔖</span>
              <p>You haven't bookmarked any verses yet.</p>
              <button
                className="btn-primary"
                onClick={() => setActiveSubTab('reader')}
              >
                Go to Scripture Reader
              </button>
            </div>
          ) : (
            <div className="bookmarks-grid">
              {bookmarks.map((bm) => (
                <div key={bm.id || `${bm.book_slug}-${bm.chapter}-${bm.verse}`} className="bookmark-card">
                  <div className="bmc-header">
                    <span className="bmc-ref">
                      {bm.book_name} {bm.chapter}:{bm.verse} ({bm.translation.toUpperCase()})
                    </span>
                    <button
                      className="bmc-delete"
                      onClick={() => bm.id && toggleBookmark(bm.verse, bm.verse_text || '')}
                      title="Delete bookmark"
                    >
                      🗑️
                    </button>
                  </div>

                  {bm.verse_text && (
                    <blockquote className="bmc-text">"{bm.verse_text}"</blockquote>
                  )}

                  {bm.note && (
                    <div className="bmc-note">
                      <strong>My Note:</strong> {bm.note}
                    </div>
                  )}

                  <div className="bmc-actions">
                    <button
                      className="btn-gold-sm"
                      onClick={() => handleJumpToPassage(bm.book_slug, bm.chapter)}
                    >
                      Open in Chapter ➔
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

