import React, { useState } from 'react';
import { PrayerRequest } from '../types';
import { ChurchAPI } from '../services/api';

interface PrayerRequestsViewProps {
  prayers: PrayerRequest[];
  onPrayerAdded: (pr: PrayerRequest) => void;
}

export const PrayerRequestsView: React.FC<PrayerRequestsViewProps> = ({
  prayers,
  onPrayerAdded
}) => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [requestText, setRequestText] = useState('');
  const [isAnonymous, setIsAnonymous] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [successMsg, setSuccessMsg] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!requestText.trim()) return;

    setSubmitting(true);
    try {
      const newPr = await ChurchAPI.submitPrayerRequest({
        name: isAnonymous ? 'Anonymous' : name || 'Church Member',
        email,
        request_text: requestText,
        is_anonymous: isAnonymous
      });
      onPrayerAdded(newPr);
      setRequestText('');
      setName('');
      setEmail('');
      setSuccessMsg(true);
      setTimeout(() => setSuccessMsg(false), 4000);
    } catch (err) {
      alert('Could not submit prayer request. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="prayers-view animate-fade-in">
      <div className="page-header">
        <h1 className="page-title">Prayer Requests &amp; Intercession</h1>
        <p className="page-subtitle">
          "The effective, fervent prayer of a righteous man avails much." — James 5:16
        </p>
      </div>

      <div className="prayers-layout">
        {/* Submission Form */}
        <div className="prayer-form-card">
          <h2>Submit a Prayer Request</h2>
          <p>Our pastors and intercessory prayer team pray over every request.</p>

          {successMsg && (
            <div className="alert-success">
              ✓ Your prayer request has been submitted to the pastoral team!
            </div>
          )}

          <form onSubmit={handleSubmit} className="prayer-form">
            <div className="form-group">
              <label>Your Name (Optional)</label>
              <input
                type="text"
                placeholder="Leave blank or enter name"
                value={name}
                disabled={isAnonymous}
                onChange={(e) => setName(e.target.value)}
              />
            </div>

            <div className="form-group">
              <label>Email Address (Confidential)</label>
              <input
                type="email"
                placeholder="For pastoral follow-up"
                value={email}
                disabled={isAnonymous}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input
                  type="checkbox"
                  checked={isAnonymous}
                  onChange={(e) => setIsAnonymous(e.target.checked)}
                />
                Keep my request completely Anonymous
              </label>
            </div>

            <div className="form-group">
              <label>Prayer Request / Praise Report *</label>
              <textarea
                required
                rows={4}
                placeholder="Share what is on your heart for prayer..."
                value={requestText}
                onChange={(e) => setRequestText(e.target.value)}
              />
            </div>

            <button type="submit" className="btn-primary" disabled={submitting}>
              {submitting ? 'Submitting...' : '🙏 Submit Prayer Request'}
            </button>
          </form>
        </div>

        {/* Community Prayer Wall */}
        <div className="prayers-wall">
          <h2>Community Prayer Wall</h2>
          <div className="prayers-list">
            {prayers.map((pr) => (
              <div key={pr.id} className="prayer-card">
                <div className="pc-header">
                  <span className="pc-user">
                    {pr.is_anonymous ? '🕊️ Anonymous Sister/Brother' : `🕊️ ${pr.name || 'Member'}`}
                  </span>
                  {pr.is_answered && (
                    <span className="badge-answered">✓ Praise God! Answered</span>
                  )}
                </div>
                <p className="pc-text">"{pr.request_text}"</p>
                <div className="pc-footer">
                  <span className="pc-praying">Joining in prayer with you</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

