              <strong>Office Hours</strong>
              <p>Tuesday – Friday: 09:00 AM – 04:00 PM</p>
            </div>
          </div>

          <div className="ci-item">
            <span className="ci-icon">✉️</span>
            <div>
              <strong>Email &amp; Pastoral Inquiries</strong>
              <p>pastor@gracechurch.org</p>
            </div>
          </div>

          <div className="ci-item">
            <span className="ci-icon">📞</span>
            <div>
              <strong>Helpline &amp; Prayer Intercession</strong>
              <p>+1 (555) 777-FAITH</p>
            </div>
          </div>
        </div>

        <div className="contact-form-card">
          <h2>Send a Message</h2>
          {submitted ? (
            <div className="alert-success">
              ✓ Thank you! Your message has been sent to our ministry leadership.
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="contact-form">
              <div className="form-group">
                <label>Your Name *</label>
                <input
                  required
                  type="text"
                  placeholder="Full name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>

              <div className="form-group">
                <label>Email Address *</label>
                <input
                  required
                  type="email"
                  placeholder="name@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>

              <div className="form-group">
                <label>Phone Number (Optional)</label>
                <input
                  type="tel"
                  placeholder="Contact phone"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                />
              </div>

              <div className="form-group">
                <label>Message *</label>
                <textarea
                  required
                  rows={4}
                  placeholder="How can we assist you in your spiritual journey?"
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                />
              </div>

              <button type="submit" className="btn-primary" disabled={loading}>
                {loading ? 'Sending...' : '✉️ Send Message'}
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

