import React, { useState, useEffect } from 'react';
import './App.css';
import { Header } from './components/Header';
import { HomeView } from './components/HomeView';
import { BibleReaderView } from './components/BibleReaderView';
import { SermonsView } from './components/SermonsView';
import { PrayerRequestsView } from './components/PrayerRequestsView';
import { EventsView } from './components/EventsView';
import { ContactView } from './components/ContactView';
import { Footer } from './components/Footer';

import {
  BookMeta,
  DailyVerse,
  Announcement,
  ChurchEvent,
  Sermon,
  PrayerRequest,
  HealthStatus
} from './types';
import { BibleAPI, ChurchAPI } from './services/api';

export const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<string>('home');
  const [theme, setTheme] = useState<string>(
    () => localStorage.getItem('grace_church_theme') || 'dark'
  );

  // Global State
  const [books, setBooks] = useState<BookMeta[]>([]);
  const [dailyVerse, setDailyVerse] = useState<DailyVerse | null>(null);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [events, setEvents] = useState<ChurchEvent[]>([]);
  const [sermons, setSermons] = useState<Sermon[]>([]);
  const [prayers, setPrayers] = useState<PrayerRequest[]>([]);
  const [health, setHealth] = useState<HealthStatus | null>(null);

  // Target passage for Bible reader navigation
  const [targetBookSlug, setTargetBookSlug] = useState<string>('genesis');
  const [targetChapter, setTargetChapter] = useState<number>(1);

  // Theme application
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('grace_church_theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme((prev) => (prev === 'dark' ? 'light' : 'dark'));
  };

  // Initial Data Fetching
  useEffect(() => {
    // Health check
    BibleAPI.getHealth()
      .then((h) => setHealth(h))
      .catch((err) => console.warn('Backend health check error:', err));

    // Books
    BibleAPI.getBooks()
      .then((b) => setBooks(b))
      .catch((err) => console.warn('Could not load books:', err));

    // Daily Verse
    BibleAPI.getDailyVerse()
      .then((dv) => setDailyVerse(dv))
      .catch((err) => console.warn('Could not load daily verse:', err));

    // Announcements
    ChurchAPI.getAnnouncements()
      .then((a) => setAnnouncements(a))
      .catch((err) => console.warn('Could not load announcements:', err));

    // Events
    ChurchAPI.getEvents()
      .then((ev) => setEvents(ev))
      .catch((err) => console.warn('Could not load events:', err));

    // Sermons
    ChurchAPI.getSermons()
      .then((s) => setSermons(s))
      .catch((err) => console.warn('Could not load sermons:', err));

    // Prayer Requests
    ChurchAPI.getPrayerRequests()
      .then((pr) => setPrayers(pr))
      .catch((err) => console.warn('Could not load prayer requests:', err));
  }, []);

  const handleNavigateToBible = (bookSlug?: string, chapter?: number) => {
    if (bookSlug) setTargetBookSlug(bookSlug);
    if (chapter) setTargetChapter(chapter);
    setActiveTab('bible');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePrayerAdded = (newPr: PrayerRequest) => {
    setPrayers([newPr, ...prayers]);
  };

  return (
    <div className="church-app-root">
      {/* Navigation Header */}
      <Header
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        theme={theme}
        toggleTheme={toggleTheme}
        health={health}
      />

      {/* Main Content Area */}
      <main className="main-content">
        {activeTab === 'home' && (
          <HomeView
            dailyVerse={dailyVerse}
            announcements={announcements}
            events={events}
            onNavigateToBible={handleNavigateToBible}
            onNavigateToTab={(tab) => setActiveTab(tab)}
          />
        )}

        {activeTab === 'bible' && (
          <BibleReaderView
            books={books}
            initialBookSlug={targetBookSlug}
            initialChapter={targetChapter}
          />
        )}

        {activeTab === 'sermons' && (
          <SermonsView sermons={sermons} />
        )}

        {activeTab === 'prayers' && (
          <PrayerRequestsView
            prayers={prayers}
            onPrayerAdded={handlePrayerAdded}
          />
        )}

        {activeTab === 'events' && (
          <EventsView events={events} />
        )}

        {activeTab === 'contact' && (
          <ContactView />
        )}
      </main>

      {/* Footer */}
      <Footer />
    </div>
  );
};

export default App;
